package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.widget.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.UiDevice;import org.junit.Test;import java.io.File;import java.time.*;import java.util.*;import static org.junit.Assert.*;
/** Actual local search and record navigation, with private saved data and no outputs. */
public final class SearchFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);SearchActivity activity;RecordReportActivity report;
    void await(java.util.function.BooleanSupplier condition)throws Exception{long end=SystemClock.elapsedRealtime()+8000;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(20);assertTrue("Search state ready",condition.getAsBoolean());}
    View find(View root,String text){if(text.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())||root instanceof TextView&&text.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View view=find(group.getChildAt(n),text);if(view!=null)return view;}return null;}
    boolean shown(String text){boolean[] yes={false};i.runOnMainSync(()->yes[0]=activity!=null&&activity.hasWindowFocus()&&find(activity.getWindow().getDecorView(),text)!=null);return yes[0];}
    void query(String value)throws Exception{i.runOnMainSync(()->((EditText)find(activity.getWindow().getDecorView(),"Search query")).setText(value));}
    void click(String text)throws Exception{await(()->shown(text));Rect[] bounds={null};i.runOnMainSync(()->{View view=find(activity.getWindow().getDecorView(),text);while(!view.isClickable()&&view.getParent() instanceof View)view=(View)view.getParent();assertTrue(view.isEnabled()&&view.isClickable());Rect visible=new Rect();assertTrue(view.getGlobalVisibleRect(visible));assertEquals(view.getHeight(),visible.height());assertTrue(view.getHeight()>=Design.dp(c,48));int[] pos=new int[2];view.getLocationOnScreen(pos);bounds[0]=new Rect(pos[0],pos[1],pos[0]+view.getWidth(),pos[1]+view.getHeight());});assertTrue(d.click(bounds[0].centerX(),bounds[0].centerY()));}
    void capture(String frame)throws Exception{i.waitForIdleSync();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(d.takeScreenshot(new File(folder,"search-"+frame+".png")));}
    @Test public void queryResultsRecreationAndSavedRecordOpenUseRealControls()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);String name="search-ui-"+UUID.randomUUID()+".db";Records.Factory old=Records.factory;Map<String,?> prefs=new HashMap<>(Prefs.of(c).getAll());
        try(Store store=new Store(c,name)){Records.factory=context->new Store(context,name);long now=System.currentTimeMillis();RecordDraft draft=new RecordDraft(now-86400000,now-57600000);draft.note="Evening exercise";long id=Records.create(store,draft,ZoneId.of("UTC"),now);String before=BackupFingerprint.read(store);Instrumentation.ActivityMonitor monitor=i.addMonitor(SearchActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,SearchActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Private local search fixture").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(SearchActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}await(()->shown("Search your alarms, sleep records and settings."));capture("empty");query("nothing-matches");await(()->shown("No matching results"));capture("no-results");query("exercise");await(()->shown("1 result"));capture("record");SearchActivity previous=activity;monitor=i.addMonitor(SearchActivity.class.getName(),null,false);try{i.runOnMainSync(previous::recreate);activity=(SearchActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}await(()->shown("1 result"));capture("recreated");String title=RecordUi.date(draft.end,ZoneId.of("UTC"));monitor=i.addMonitor(RecordReportActivity.class.getName(),null,false);try{click(title);report=(RecordReportActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(report);assertEquals(id,report.getIntent().getLongExtra("record",0));}finally{i.removeMonitor(monitor);}report.awaitReaders(8000);assertEquals(before,BackupFingerprint.read(store));assertEquals(prefs,Prefs.of(c).getAll());
        }finally{if(report!=null&&!report.isDestroyed()){RecordReportActivity owned=report;i.runOnMainSync(owned::finish);await(owned::isDestroyed);owned.awaitReaders(8000);}if(activity!=null&&!activity.isDestroyed()){SearchActivity owned=activity;i.runOnMainSync(owned::finish);await(owned::isDestroyed);assertTrue(owned.awaitReaders(8000));}Records.factory=old;assertTrue(c.deleteDatabase(name));assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertEquals(prefs,Prefs.of(c).getAll());}
    }
}
